-- Вывод статистики загруженных данных
SELECT 
  (SELECT COUNT(*) FROM profiles) as "Профилей",
  (SELECT COUNT(*) FROM facilities) as "Объектов",
  (SELECT COUNT(*) FROM positions) as "Должностей",
  (SELECT COUNT(*) FROM employees) as "Сотрудников",
  (SELECT COUNT(*) FROM shift_templates) as "Шаблонов смен",
  (SELECT COUNT(*) FROM schedules) as "Графиков",
  (SELECT COUNT(*) FROM timesheets) as "Табелей";
